import{_ as t,c as a,o as n,ag as r}from"./chunks/framework.D6L8gzMI.js";const u=JSON.parse('{"title":"3.27","description":"","frontmatter":{"title":"3.27"},"headers":[],"relativePath":"review/3-27.md","filePath":"review/3-27.md","lastUpdated":1743095562000}'),s={name:"review/3-27.md"};function i(o,e,d,l,h,g){return n(),a("div",null,e[0]||(e[0]=[r('<h2 id="hash-table-and-binary-search-tree-bst" tabindex="-1">Hash Table and Binary Search Tree (BST) <a class="header-anchor" href="#hash-table-and-binary-search-tree-bst" aria-label="Permalink to &quot;Hash Table and Binary Search Tree (BST)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Binary Search Tree（BST）</th><th>Hash Table</th></tr></thead><tbody><tr><td><strong>Lookup Complexity</strong></td><td>O(log n)（balanced） / O(n) （unbalanced）</td><td>O(1)（average） / O(n)（worst，severe hash collisions）</td></tr><tr><td><strong>Insertion/Deletion Complexity</strong></td><td>O(log n)（balanced） / O(n) （unbalanced）</td><td>O(1)（average） / O(n)（severe hash collisions）</td></tr><tr><td><strong>Ordered Data</strong></td><td>Yes（sorted data, traversal）</td><td>No（unordered storage）</td></tr><tr><td><strong>Range Queries</strong></td><td>Yes（O(log n)）</td><td>No（full scan）</td></tr><tr><td><strong>Memory Usage</strong></td><td>Lower（stores pointers）</td><td>Higher（hash buckets &amp; potential resizing）</td></tr><tr><td><strong>Balance Maintenance</strong></td><td>Required（AVL、Red-Black Tree）</td><td>Not required</td></tr><tr><td><strong>Hash Collisions</strong></td><td>No impact</td><td>can affect lookup efficiency</td></tr><tr><td><strong>Best Use Cases</strong></td><td><strong>Sorting, range queries</strong>（database indexes、ranking systems）</td><td><strong>Fast lookups</strong>（caching、database indexing、key-value stores）</td></tr></tbody></table><table tabindex="0"><thead><tr><th><strong>Use Cases</strong></th><th><strong>Recommended Data Structure</strong></th><th><strong>Reason</strong></th></tr></thead><tbody><tr><td><strong>Lookup single element</strong></td><td>Hash Table</td><td>O(1) lookup，best performance</td></tr><tr><td><strong>Sorting &amp; Range Queries</strong></td><td>Binary Search Tree</td><td>Support in-order traversal and range queries like <code>[a, b]</code></td></tr><tr><td><strong>Caching（e.g., Redis）</strong></td><td>Hash Table</td><td>O(1) lookup，ideal for caching</td></tr><tr><td><strong>Database Indexing</strong></td><td>B-Tree / B+Tree</td><td>Optimized for disk storage, balanced and efficient</td></tr><tr><td><strong>Streaming Data Processing</strong></td><td>Binary Tree</td><td>Maintains ordered data dynamically (e.g., Top-K ranking)</td></tr><tr><td><strong>Symbol Table (Compiler)</strong></td><td>Hash Table</td><td>Fast variable lookup</td></tr><tr><td><strong>Deduplication &amp; Counting</strong></td><td>Hash Table</td><td>O(1) lookup for checking existence</td></tr></tbody></table><h2 id="b-tree-in-database" tabindex="-1">B+ Tree in database <a class="header-anchor" href="#b-tree-in-database" aria-label="Permalink to &quot;B+ Tree in database&quot;">​</a></h2><p>Databases often store huge amounts of data that cannot fit in memory. Since accessing data from disk is slow, databases need efficient structures to minimize disk reads.</p><p>A B+ Tree is a self-balancing tree that keeps data sorted and allows efficient range queries and fast lookups, making it ideal for indexing.</p><p><strong>Structure of B+ Tree:</strong></p><p>A B+ Tree is similar to a Binary Search Tree (BST) but with the following differences:</p><ul><li>Each node contains multiple keys instead of just one (making it a multi-way tree).</li><li>Internal nodes (non-leaf nodes) only store keys for navigation; actual data is stored only in leaf nodes.</li><li>Leaf nodes are linked, forming a doubly linked list for efficient range queries.</li><li>The tree remains balanced through self-adjusting mechanisms like splitting and merging.</li></ul><table tabindex="0"><thead><tr><th>Feature</th><th>B+ Tree Advantage</th></tr></thead><tbody><tr><td><strong>Balanced Structure</strong></td><td>Always balanced → Ensures consistent O(log n) lookup time</td></tr><tr><td><strong>Efficient Disk I/O</strong></td><td>Nodes contain multiple keys → Fewer disk accesses</td></tr><tr><td><strong>Fast Range Queries</strong></td><td>Leaf nodes are linked → Supports sequential access efficiently</td></tr><tr><td><strong>High Fan-Out</strong></td><td>Reduces tree height → Fewer levels = fewer disk reads</td></tr><tr><td><strong>Better Caching</strong></td><td>Internal nodes store only keys → More fit in memory, reducing disk reads</td></tr></tbody></table><h3 id="how-b-trees-handle-queries-efficiently" tabindex="-1">How B+ Trees Handle Queries Efficiently <a class="header-anchor" href="#how-b-trees-handle-queries-efficiently" aria-label="Permalink to &quot;How B+ Trees Handle Queries Efficiently&quot;">​</a></h3><h4 id="point-query-finding-a-single-value" tabindex="-1">Point Query (Finding a Single Value) <a class="header-anchor" href="#point-query-finding-a-single-value" aria-label="Permalink to &quot;Point Query (Finding a Single Value)&quot;">​</a></h4><ol><li>Start from the root.</li><li>Move down the appropriate child based on key comparisons.</li><li>Reach the leaf node and return the value.</li></ol><p><strong>Complexity</strong>: O(log n)</p><h4 id="range-query-finding-values-in-a-range" tabindex="-1">Range Query (Finding Values in a Range) <a class="header-anchor" href="#range-query-finding-values-in-a-range" aria-label="Permalink to &quot;Range Query (Finding Values in a Range)&quot;">​</a></h4><ol><li>Navigate to the leftmost matching leaf node.</li><li>Follow the linked list of leaf nodes to fetch all values in the range.</li></ol><p><strong>Complexity</strong>: O(log n) for lookup + O(k) for k results (much faster than scanning the entire table).</p><h4 id="insertion-deletion" tabindex="-1">Insertion &amp; Deletion <a class="header-anchor" href="#insertion-deletion" aria-label="Permalink to &quot;Insertion &amp; Deletion&quot;">​</a></h4><ul><li>Insertion: If a node overflows, it splits and propagates the split upwards.</li><li>Deletion: If a node underflows, it borrows keys from siblings or merges nodes.</li></ul><p>These operations keep the tree balanced while ensuring efficient query performance.</p><h2 id="how-python-implements-set-internally" tabindex="-1">How Python Implements set Internally <a class="header-anchor" href="#how-python-implements-set-internally" aria-label="Permalink to &quot;How Python Implements set Internally&quot;">​</a></h2><p>In Python, a set is implemented using a hash table, specifically a dictionary-like structure where only the keys are stored (without values). It allows for fast lookups, insertions, and deletions with an average time complexity of O(1).</p><ul><li>A dynamic array of slots (buckets) to store elements</li><li>A hash function to map elements to slots</li><li>Open addressing for collision resolution</li></ul><p>Each element in a set must be hashable (i.e., have a <strong>hash</strong> method and be immutable).</p>',24)]))}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
